INSERT INTO `Announcements` VALUES (1,'Nowe zasady bezpieczeństwa','Informujemy, że wprowadziliśmy nowe zasady bezpieczeństwa na lotnisku. Prosimy o zapoznanie się z nimi.','2026-03-03 23:59:00',NULL,1,'wazne'),(2,'Zmiana w harmonogramie','Z powodu opóźnień zmieniono godziny odlotów i przylotów','2024-04-30 23:59:00',NULL,1,'zmiana'),(3,'Znaleziono klucze','Obsługa prosi o odbiór znalezionych kluczy w informacji.','2024-04-20 23:59:59',NULL,1,'informacja'),(4,'Zmiana w harmonogramie','Z powodu opóźnień zmieniono godziny odlotów i przylotów','2024-04-30 23:59:00',NULL,1,'zmiana'),(6,'Awaria systemu odprawy bagażu','Wystąpiła awaria systemu sortowania bagażu w strefie B. Możliwe opóźnienia w obsłudze rejestrowanego bagażu. Zespół techniczny prowadzi prace naprawcze.','2026-06-30 18:06:00','2026-02-05 13:07:25',1,'wazne'),(7,'Test systemu alarmowego','W środę o godzinie 13:00 odbędzie się test systemu alarmowego. Nie są wymagane żadne działania.','2026-02-11 12:59:00','2026-02-05 13:09:00',1,'informacja'),(8,'Darmowe Wi-Fi na terenie terminala','Na całym terenie terminala dostępna jest bezpłatna sieć Wi-Fi „Airport_Free”.','2027-01-05 13:32:00','2026-02-05 13:33:02',1,'informacja'),(9,'Strefa dla rodzin z dziećmi','Strefa rodzin znajduje się przy bramkach B5–B7. Dostępne są miejsca do odpoczynku i przewijania.','2027-01-05 13:33:00','2026-02-05 13:33:24',1,'informacja'),(10,'Czasowa awaria części stanowisk odprawy','Część stanowisk odprawy jest chwilowo niedostępna. Prosimy korzystać z automatów self-check-in lub stanowisk alternatywnych.','2026-03-01 13:34:00','2026-02-05 13:35:06',1,'wazne');
